def ring_all_reduce(bufs):
    # bufs[r]: GPU r의 텐서를 N개 청크로 나눈 리스트
    N = len(bufs)
    # 1단계 Reduce-Scatter: N-1 스텝 (GPU 동시 송신)
    for s in range(N - 1):
        for r in range(N):
            c = (r - s) % N  # GPU r이 이번에 보낼 청크
            bufs[(r + 1) % N][c] += bufs[r][c]
    # 이 시점 GPU r은 청크 (r+1)%N 의 전체 합 보유
    # 2단계 All-Gather: N-1 스텝으로 완성 청크 전파
    for s in range(N - 1):
        for r in range(N):
            c = (r + 1 - s) % N
            bufs[(r + 1) % N][c] = bufs[r][c]
    return bufs  # 모든 GPU가 동일한 합계 보유

# GPU당 전송량 2(N-1)/N × 데이터 → GPU 수와 거의 무관
